void require(bool yes,const char* text){if(!yes)throw Error(1,text);}
void check(const Limits& limits){if(limits.cancellation&&limits.cancellation->load(std::memory_order_relaxed))throw Error(3,"Experiment bundle operation cancelled.");}
std::string hash(const Json& json){return ode::detail::sha256(json.dump());}
void keys(const Json& json,std::initializer_list<const char*> names){require(json.is_object()&&json.size()==names.size(),"Experiment bundle object has an unexpected schema.");for(const auto* name:names)require(json.contains(name),"Experiment bundle object is incomplete.");}
std::string text(const Json& json,std::size_t maximum=4096){require(json.is_string(),"Expected an experiment bundle text field.");const auto value=json.get<std::string>();require(value.size()<=maximum,"Experiment bundle text exceeds its bound.");return value;}
uint64_t integer(const Json& value){require(value.is_number_integer()&&(value.is_number_unsigned()||value.get<int64_t>()>=0),"Bundle dimensions/version/counts require nonnegative exact integers.");return value.get<uint64_t>();}
bool hashText(const std::string& value){return value.size()==64&&std::all_of(value.begin(),value.end(),[](unsigned char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f');});}
const char alphabet[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
std::string base64(std::string_view bytes){std::string output;output.reserve((bytes.size()+2)/3*4);for(std::size_t at=0;at<bytes.size();at+=3){const unsigned a=static_cast<unsigned char>(bytes[at]),b=at+1<bytes.size()?static_cast<unsigned char>(bytes[at+1]):0,c=at+2<bytes.size()?static_cast<unsigned char>(bytes[at+2]):0;output+=alphabet[a>>2];output+=alphabet[((a&3)<<4)|(b>>4)];output+=at+1<bytes.size()?alphabet[((b&15)<<2)|(c>>6)]:'=';output+=at+2<bytes.size()?alphabet[c&63]:'=';}return output;}
