Json context(const Context& value){require(value.algebra.size()<=128&&value.language.size()<=32&&std::isfinite(value.gamma)&&value.gamma>=0&&value.gamma<=1,"Invalid experiment algebra context.");return {{"algebra",value.algebra},{"gamma",value.gamma},{"language",value.language},{"precision_bits",value.precision},{"integer_bits",value.integer}};}
Context context(const Json& value){keys(value,{"algebra","gamma","language","precision_bits","integer_bits"});Context result;result.algebra=text(value.at("algebra"),128);result.language=text(value.at("language"),32);require(value.at("gamma").is_number(),"Bundle gamma must be a finite real value.");result.gamma=value.at("gamma").get<double>();require(std::isfinite(result.gamma)&&result.gamma>=0&&result.gamma<=1,"Invalid bundle gamma context.");const auto precision=integer(value.at("precision_bits")),bits=integer(value.at("integer_bits"));require(precision<=1024&&bits<=1024,"Invalid bundle numerical precision declaration.");result.precision=precision;result.integer=bits;return result;}
std::string typedText(const Json& record,const char* name){if(!record.is_object()||!record.contains(name))return {};const auto& value=record.at(name);if(!value.is_object()||value.value("type",std::string())!="string"||!value.contains("value")||!value.at("value").is_string())return {};return value.at("value").get<std::string>();}
bool typedInteger(const Json& record,const char* name,int64_t expected){if(!record.is_object()||!record.contains(name))return false;const auto& value=record.at(name);return value.is_object()&&value.value("type",std::string())=="integer"&&value.contains("value")&&value.at("value").is_number_integer()&&value.at("value")==expected;}
bool provenance(const Json& value){if(!value.is_object()||value.value("type",std::string())!="record"||!value.contains("value"))return false;const auto& fields=value.at("value");if(!fields.is_object()||fields.size()!=4||typedText(fields,"format")!="PentarnionProvenance"||!typedInteger(fields,"version",1)||!fields.contains("scientific")||!fields.contains("execution"))return false;const auto& scientific=fields.at("scientific");const auto& execution=fields.at("execution");if(scientific.value("type",std::string())!="record"||execution.value("type",std::string())!="record"||!scientific.contains("value")||!execution.contains("value"))return false;const auto& s=scientific.at("value");const auto& e=execution.at("value");if(!s.is_object()||!e.is_object()||s.size()!=9||e.size()!=9)return false;for(const auto* key:{"source_hash","import_hashes","native_keys","algebra","gamma","language","solver_backend","precision_bits","integer_bits"})if(!s.contains(key))return false;for(const auto* key:{"platform","source_directory","cache_directory","dependency_locations","requested_threads","granted_threads","compiler_attempts","cache_hits","compilation_seconds"})if(!e.contains(key))return false;return true;}
struct Scan{const Limits& limits;uint64_t nodes=0;void tick(unsigned depth){if((++nodes&1023)==0)check(limits);if(depth>64||nodes>16000000)throw Error(7,"Bundle typed data exceeds its nesting/node allowance.");}};
bool pentarnion(const Json& entry,Scan& scan,unsigned depth){scan.tick(depth);require(entry.is_object()&&entry.contains("type")&&entry.contains("value"),"Invalid typed experiment payload entry.");const auto type=text(entry.at("type"),64);const auto& value=entry.at("value");if(type=="pentarnion"||type=="pentarnionmatrix")return true;if(type=="solution"){require(entry.contains("state_widths")&&entry.at("state_widths").is_array(),"Invalid typed solution metadata.");for(const auto& width:entry.at("state_widths"))if(integer(width)==5)return true;return false;}if(type=="record"||type=="options"){require(value.is_object()&&value.size()<=64,"Invalid typed record in experiment payload.");const auto format=typedText(value,"format");if(typedText(value,"kind")=="pentarnion"||typedText(value,"coordinate_kind")=="pentarnion_coefficients"||(value.contains("gamma")&&value.contains("values")&&typedInteger(value,"width",5)))return true;if((format=="PentarnionND-v1"&&typedText(value,"kind")=="pentarnion")||(format=="PentarnionSurfaceMesh-v1"&&typedText(value,"coordinate_kind")=="pentarnion_coefficients")||(format=="PentarnionSurfaceSolution-v1"&&typedInteger(value,"width",5))||format=="PentarnionExactCoefficients-v1")return true;for(const auto& child:value.items())if(pentarnion(child.value(),scan,depth+1))return true;return false;}if(type=="tuple"){require(value.is_array()&&value.size()<=16,"Invalid typed result tuple.");for(const auto& child:value)if(pentarnion(child,scan,depth+1))return true;return false;}static const std::set<std::string> real{"integer","real","complex","string","realmatrix","logicalmatrix","integer range","real range"};require(real.contains(type),"Unsupported typed data kind in experiment bundle.");return false;}
Json projection(const Json& value,Scan& scan,unsigned depth){scan.tick(depth);Json result=value;if(value.is_object()){for(auto item=result.begin();item!=result.end();++item)item.value()=projection(item.value(),scan,depth+1);if(provenance(value))result["value"]["execution"]={{"type","record"},{"value",Json::object()}};}else if(value.is_array())for(auto& item:result)item=projection(item,scan,depth+1);return result;}
std::filesystem::path relativePath(const std::string& original){require(!original.empty()&&original.size()<=1024&&original.find('\0')==std::string::npos&&original.find(':')==std::string::npos,"Artifact names require bounded portable relative paths without NUL/drive/ADS syntax.");std::string path=original;std::replace(path.begin(),path.end(),'\\','/');require(path.front()!='/',"Artifact names must be project-relative paths.");std::size_t at=0;while(at<path.size()){const auto end=path.find('/',at);const auto part=path.substr(at,end==std::string::npos?path.size()-at:end-at);require(!part.empty()&&part!="."&&part!=".."&&part.back()!='.'&&part.back()!=' ',"Artifact paths cannot traverse, contain empty components or use ambiguous trailing dots/spaces.");for(const unsigned char c:part)require(c>=32&&c!=127,"Artifact paths contain control characters.");auto stem=part.substr(0,part.find('.'));std::transform(stem.begin(),stem.end(),stem.begin(),[](unsigned char c){return static_cast<char>(std::toupper(c));});require(stem!="CON"&&stem!="PRN"&&stem!="AUX"&&stem!="NUL"&&!(stem.size()==4&&(stem.starts_with("COM")||stem.starts_with("LPT"))&&stem[3]>='1'&&stem[3]<='9'),"Artifact paths cannot refer to reserved device names.");if(end==std::string::npos)break;at=end+1;require(at<path.size(),"Artifact filename is missing.");}return std::filesystem::path(std::u8string(reinterpret_cast<const char8_t*>(path.data()),path.size()));}
bool within(const std::filesystem::path& root,const std::filesystem::path& path){auto a=root.begin(),b=path.begin();for(;a!=root.end();++a,++b){if(b==path.end())return false;
#ifdef _WIN32
const auto x=a->native(),y=b->native();if(CompareStringOrdinal(x.c_str(),static_cast<int>(x.size()),y.c_str(),static_cast<int>(y.size()),TRUE)!=CSTR_EQUAL)return false;
#else
if(*a!=*b)return false;
#endif
}return true;}
