struct Handle{HANDLE value=INVALID_HANDLE_VALUE;explicit Handle(HANDLE handle):value(handle){}~Handle(){if(value!=INVALID_HANDLE_VALUE)CloseHandle(value);}Handle(const Handle&)=delete;Handle& operator=(const Handle&)=delete;};
std::filesystem::path physical(HANDLE handle){std::vector<wchar_t> buffer(32768);const auto count=GetFinalPathNameByHandleW(handle,buffer.data(),static_cast<DWORD>(buffer.size()),FILE_NAME_NORMALIZED|VOLUME_NAME_DOS);require(count>0&&count<buffer.size(),"Cannot resolve an artifact's physical Windows path.");std::wstring value(buffer.data(),count);if(value.starts_with(L"\\\\?\\UNC\\"))value=L"\\\\"+value.substr(8);else if(value.starts_with(L"\\\\?\\"))value.erase(0,4);return std::filesystem::path(value).lexically_normal();}
bool ancestor(HANDLE root,const std::filesystem::path& target){BY_HANDLE_FILE_INFORMATION base{};if(!GetFileInformationByHandle(root,&base)||!(base.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY))return false;for(auto path=target.parent_path();!path.empty();){Handle directory(CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr));BY_HANDLE_FILE_INFORMATION info{};if(directory.value==INVALID_HANDLE_VALUE||!GetFileInformationByHandle(directory.value,&info))return false;if(info.dwVolumeSerialNumber==base.dwVolumeSerialNumber&&info.nFileIndexHigh==base.nFileIndexHigh&&info.nFileIndexLow==base.nFileIndexLow)return true;const auto parent=path.parent_path();if(parent==path)break;path=parent;}return false;}
std::string windowsArtifact(const std::filesystem::path& root,const std::filesystem::path& local,const Limits& limits){Handle directory(CreateFileW(root.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS,nullptr));require(directory.value!=INVALID_HANDLE_VALUE,"Cannot open the artifact project root.");Handle file(CreateFileW((root/local).c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_SEQUENTIAL_SCAN,nullptr));require(file.value!=INVALID_HANDLE_VALUE,"Cannot capture the selected artifact (missing, inaccessible or being modified).");const auto base=physical(directory.value),target=physical(file.value);require(within(base,target)&&ancestor(directory.value,target),"Artifact physical path escapes the project root through a symlink/junction/reparse point.");BY_HANDLE_FILE_INFORMATION information{};require(GetFileInformationByHandle(file.value,&information)&&!(information.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY),"Selected artifact is not a regular file.");LARGE_INTEGER size{};require(GetFileSizeEx(file.value,&size)&&size.QuadPart>=0&&static_cast<uint64_t>(size.QuadPart)<=limits.maximumArtifactBytes,"Selected artifact exceeds its byte allowance.");std::string bytes(static_cast<std::size_t>(size.QuadPart),'\0');for(std::size_t at=0;at<bytes.size();){check(limits);DWORD received=0;const auto count=static_cast<DWORD>(std::min<std::size_t>(8192,bytes.size()-at));require(ReadFile(file.value,bytes.data()+at,count,&received,nullptr)&&received>0,"Selected artifact could not be read completely.");at+=received;}check(limits);return bytes;}
