Json payload(const Json& document,const Context& current,bool allowRealContext,const Limits& limits){const auto info=inspect(document,current,limits);require(!info.migration,"Experiment version/language/algebra/precision requires explicit compatibility migration; no data were decoded.");if(!info.compatible){const bool real=allowRealContext&&!info.pentarnion&&info.context.algebra==current.algebra&&info.context.language==current.language&&info.context.precision==current.precision&&info.context.integer==current.integer;require(real,info.pentarnion?"Experiment contains typed/context-bearing Pentarnion data; foreign gamma load is forbidden.":"Experiment context differs; compatible real-only gamma data requires explicit allow_real_context=1.");}return document.at("payload");}
